"""The structure of config.yaml: everything the tool knows about one Jira board.

config.yaml is generated by `jira-agent init` and can be edited by hand
(e.g. to add nicknames). It holds no secrets; those stay in .env.
"""

from __future__ import annotations

from pathlib import Path

import yaml
from pydantic import BaseModel, Field, ValidationError, model_validator

DEFAULT_CONFIG_PATH = Path("config.yaml")
CONFIG_HEADER = (
    "# Jira Sprint Agent board settings.\n"
    "# Generated by `jira-agent init`. Safe to edit by hand: e.g. add nicknames\n"
    "# under each team member's `aliases`. Re-run `jira-agent init` to regenerate.\n"
    "# Contains no secrets (those live in .env).\n\n"
)


class IssueType(BaseModel):
    id: str
    name: str
    subtask: bool = False
    hierarchy_level: int = 0


class Status(BaseModel):
    id: str
    name: str
    category: str  # 'new' (To Do), 'indeterminate' (In Progress), 'done'


class LinkType(BaseModel):
    id: str
    name: str
    outward: str
    inward: str


class TeamMember(BaseModel):
    account_id: str
    name: str
    aliases: list[str] = Field(default_factory=list)

    def matches(self, text: str) -> bool:
        """True if `text` is this person's name or one of their nicknames."""
        wanted = text.strip().lower()
        return wanted == self.name.lower() or wanted in (a.lower() for a in self.aliases)


class Fields(BaseModel):
    story_points: str | None = None
    sprint: str | None = None
    flagged: str | None = None
    start_date: str | None = None
    due_date: str = "duedate"


class Defaults(BaseModel):
    new_issue_type: str = "Task"
    add_new_issues_to_active_sprint: bool = True
    stale_after_days: int = 3
    timezone: str = "Africa/Nairobi"


class ClaudeSettings(BaseModel):
    model: str = "claude-sonnet-5-5"
    max_tokens: int = 8000


class Safety(BaseModel):
    dry_run_default: bool = True
    allow_sprint_start_complete: bool = True
    require_double_confirm_for: list[str] = Field(
        default_factory=lambda: ["start_sprint", "complete_sprint"]
    )


class Naming(BaseModel):
    example_summaries: list[str] = Field(default_factory=list)
    attribution_format: str = "Update from {member} (via {runner}, {date}):"


class BoardConfig(BaseModel):
    config_version: int = 1
    project_key: str
    project_name: str
    project_style: str
    board_id: int
    board_name: str
    issue_types: list[IssueType]
    statuses: dict[str, list[Status]]
    fields: Fields
    link_types: list[LinkType]
    priorities: list[str]
    team: list[TeamMember]
    defaults: Defaults = Field(default_factory=Defaults)
    claude: ClaudeSettings = Field(default_factory=ClaudeSettings)
    safety: Safety = Field(default_factory=Safety)
    naming: Naming = Field(default_factory=Naming)

    @model_validator(mode="after")
    def check_consistency(self) -> "BoardConfig":
        type_names = {t.name.lower() for t in self.issue_types}
        if self.defaults.new_issue_type.lower() not in type_names:
            raise ValueError(
                f"defaults.new_issue_type '{self.defaults.new_issue_type}' is not an "
                f"issue type in {self.project_key}. "
                f"Choose one of: {', '.join(t.name for t in self.issue_types)}"
            )
        seen: dict[str, str] = {}
        for member in self.team:
            for alias in [member.name, *member.aliases]:
                key = alias.strip().lower()
                if key in seen and seen[key] != member.account_id:
                    raise ValueError(
                        f"The name/nickname '{alias}' is used for two different team "
                        "members. Each nickname must be unique."
                    )
                seen[key] = member.account_id
        return self

    # ---- lookups used by the rest of the tool ----------------------------

    def issue_type(self, name: str) -> IssueType | None:
        wanted = name.strip().lower()
        return next((t for t in self.issue_types if t.name.lower() == wanted), None)

    def find_member(self, text: str) -> TeamMember | None:
        return next((m for m in self.team if m.matches(text)), None)

    def status_names(self, issue_type_name: str) -> list[str]:
        return [s.name for s in self.statuses.get(issue_type_name, [])]


class ConfigError(Exception):
    """config.yaml is missing or invalid. The message is written for humans."""


def load_board_config(path: Path = DEFAULT_CONFIG_PATH) -> BoardConfig:
    if not path.exists():
        raise ConfigError(
            f"{path} not found. Run `jira-agent init` to create it for your board."
        )
    try:
        data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    except yaml.YAMLError as exc:
        raise ConfigError(f"{path} isn't valid YAML (check indentation): {exc}") from exc
    try:
        return BoardConfig.model_validate(data)
    except ValidationError as exc:
        problems = [
            f"{'.'.join(str(p) for p in e['loc'])}: {e['msg']}" for e in exc.errors()
        ]
        raise ConfigError(f"{path} has problems:\n  - " + "\n  - ".join(problems)) from exc


def save_board_config(config: BoardConfig, path: Path = DEFAULT_CONFIG_PATH) -> None:
    body = yaml.safe_dump(
        config.model_dump(mode="json"), sort_keys=False, allow_unicode=True, width=100
    )
    path.write_text(CONFIG_HEADER + body, encoding="utf-8")